CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE UNIQUE, salt TEXT NOT NULL, pin_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('host','member')), color TEXT NOT NULL DEFAULT '#1d6f63', active INTEGER NOT NULL DEFAULT 1, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES members(id), expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS config (key TEXT PRIMARY KEY, val TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chores (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT 'Other', member_id TEXT NOT NULL REFERENCES members(id), amount INTEGER NOT NULL CHECK(amount>=0), due TEXT NOT NULL, recurring TEXT NOT NULL DEFAULT 'none', status TEXT NOT NULL DEFAULT 'open', published INTEGER NOT NULL DEFAULT 1, paid INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ledger (id TEXT PRIMARY KEY, member_id TEXT REFERENCES members(id), amount INTEGER NOT NULL, type TEXT NOT NULL, chore_id TEXT, note TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS once_reward ON ledger(chore_id) WHERE type='reward';
CREATE INDEX IF NOT EXISTS chores_by_member ON chores(member_id,due);
CREATE INDEX IF NOT EXISTS ledger_by_member ON ledger(member_id);